//! Randomized-sequence property tests for both escrow lifecycles (#1487).
//!
//! Core invariant, mirroring the stream conservation tests (#1085):
//! across any legal sequence of operations, `released + refunded + held`
//! always equals `deposited`, and no operation path double-spends —
//! including after a dispute or a cancellation.
//!
//! Each property drives the contract with a pseudo-random sequence of
//! operations generated by `proptest`, while a parallel *model* of the
//! documented rules predicts whether every call must succeed or fail. Any
//! divergence between the contract and the model — or any conservation
//! breach — fails the test. Failing seeds land in
//! `proptest-regressions/tests/escrow_properties.txt` (proptest's default
//! location for this file) per the existing convention — see
//! `proptest-regressions/lib.txt` from the single-file era.

use crate::tests::advance_by;
use crate::{
    EscrowRecord, EscrowStatus, MicroPayContract, MicroPayContractClient, MilestoneEscrowRecord,
    MAX_DISPUTE_TIMEOUT,
};
use proptest::prelude::*;
use soroban_sdk::{testutils::Address as _, token, Address, Env};
use std::vec::Vec;

// ─── Time-locked escrow model ────────────────────────────────────────────────

#[derive(Clone, Debug)]
enum PlainOp {
    /// `open_escrow` with a release ledger `delta` ledgers in the future.
    Open { amount: i128, delta: u32 },
    /// `release_escrow` on a (possibly unknown) id.
    TryRelease(u32),
    /// `cancel_escrow` by the stored payer on a (possibly unknown) id.
    TryCancel(u32),
    /// Move the ledger clock forward.
    Advance(u32),
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum PlainState {
    Held,
    Released,
    Refunded,
}

#[derive(Debug)]
struct PlainModel {
    /// One entry per escrow ever opened: (amount, release_ledger, state).
    escrows: Vec<(i128, u32, PlainState)>,
    sequence: u32,
}

impl PlainModel {
    fn new(sequence: u32) -> Self {
        Self {
            escrows: Vec::new(),
            sequence,
        }
    }

    /// Exactly the rules `escrow.rs` enforces, applied to the model.
    fn release_would_succeed(&self, id: u32) -> bool {
        match self.escrows.get(id as usize) {
            Some(&(_, release, state)) => state == PlainState::Held && self.sequence >= release,
            None => false,
        }
    }

    fn cancel_would_succeed(&self, id: u32) -> bool {
        match self.escrows.get(id as usize) {
            Some(&(_, release, state)) => state == PlainState::Held && self.sequence < release,
            None => false,
        }
    }

    /// released + refunded + held must always equal deposited.
    fn assert_conservation(&self) {
        let deposited: i128 = self.escrows.iter().map(|e| e.0).sum();
        let released: i128 = self
            .escrows
            .iter()
            .filter(|e| e.2 == PlainState::Released)
            .map(|e| e.0)
            .sum();
        let refunded: i128 = self
            .escrows
            .iter()
            .filter(|e| e.2 == PlainState::Refunded)
            .map(|e| e.0)
            .sum();
        let held: i128 = self
            .escrows
            .iter()
            .filter(|e| e.2 == PlainState::Held)
            .map(|e| e.0)
            .sum();
        assert_eq!(
            released + refunded + held,
            deposited,
            "conservation broken: released={released}, refunded={refunded}, held={held}, \
             deposited={deposited}"
        );
    }
}

fn plain_op_strategy() -> impl Strategy<Value = PlainOp> {
    prop_oneof![
        (1i128..5_000i128, 1u32..300u32)
            .prop_map(|(amount, delta)| PlainOp::Open { amount, delta }),
        (0u32..6u32).prop_map(PlainOp::TryRelease),
        (0u32..6u32).prop_map(PlainOp::TryCancel),
        (0u32..120u32).prop_map(PlainOp::Advance),
    ]
}

proptest! {
    #![proptest_config(ProptestConfig::with_cases(100))]

    /// Any sequence of open/release/cancel/advance operations — legal or
    /// not — keeps the time-locked escrow funds conservation intact, and
    /// every double-spend path (re-releasing, cancelling a released or
    /// expired escrow, acting on an unknown id) must fail exactly when the
    /// model says so.
    #[test]
    fn prop_plain_escrow_conservation(ops in prop::collection::vec(plain_op_strategy(), 8..40)) {
        let env = Env::default();
        env.mock_all_auths();
        let contract_id = env.register_contract(None, MicroPayContract);
        let client = MicroPayContractClient::new(&env, &contract_id);
        client.initialize(&Address::generate(&env));

        let payer = Address::generate(&env);
        let recipient = Address::generate(&env);
        let mut model = PlainModel::new(env.ledger().sequence());

        for op in ops {
            match op {
                PlainOp::Open { amount, delta } => {
                    let release = model.sequence + delta;
                    let id = client.open_escrow(&payer, &recipient, &amount, &release);
                    assert_eq!(id as usize, model.escrows.len());
                    model.escrows.push((amount, release, PlainState::Held));
                }
                PlainOp::TryRelease(id) => {
                    let expected = model.release_would_succeed(id);
                    let result = client.try_release_escrow(&id);
                    assert_eq!(result.is_ok(), expected,
                        "release({id}) ok={} but model predicted {}", result.is_ok(), expected);
                    if let Some(entry) = model.escrows.get_mut(id as usize) {
                        if expected {
                            // The contract must return exactly the escrowed amount.
                            assert_eq!(result.unwrap().unwrap(), entry.0);
                            entry.2 = PlainState::Released;
                        }
                    }
                }
                PlainOp::TryCancel(id) => {
                    let expected = model.cancel_would_succeed(id);
                    let result = client.try_cancel_escrow(&id, &payer);
                    assert_eq!(result.is_ok(), expected,
                        "cancel({id}) ok={} but model predicted {}", result.is_ok(), expected);
                    if let Some(entry) = model.escrows.get_mut(id as usize) {
                        if expected {
                            assert_eq!(result.unwrap().unwrap(), entry.0);
                            entry.2 = PlainState::Refunded;
                        }
                    }
                }
                PlainOp::Advance(k) => {
                    advance_by(&env, k);
                    model.sequence += k;
                }
            }

            // Conservation must hold after every single step, not just at
            // the end of the sequence.
            model.assert_conservation();
            for (id, (amount, _, state)) in model.escrows.iter().enumerate() {
                let record: EscrowRecord = client.get_escrow(&(id as u32));
                assert_eq!(record.amount, *amount);
                assert_eq!(record.released, *state == PlainState::Released);
                assert_eq!(record.cancelled, *state == PlainState::Refunded);
            }
        }
    }
}

// ─── Milestone escrow model ──────────────────────────────────────────────────

#[derive(Clone, Debug)]
enum MilestoneOp {
    Create {
        amount: i128,
        timeout: u32,
    },
    TryApprove(u32),
    TryDispute(u32),
    /// Reclaim attempt — exercises the dispute-timeout timing path.
    TryCancel(u32),
    Advance(u32),
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum MilestoneState {
    Pending,
    Approved,
    Disputed,
    Cancelled,
}

#[derive(Debug)]
struct TrackedEscrow {
    amount: i128,
    dispute_timeout: u32,
    /// First ledger in which reclaiming succeeds; meaningful only once disputed.
    reclaim_after: u32,
    state: MilestoneState,
}

/// Minimal harness: deployed contract + funded payer. (Field layout mirrors
/// `tests::EscrowTest`, but the property tests mint their own float.)
struct EscrowHarness {
    env: Env,
    contract_id: Address,
    token: Address,
    payer: Address,
    recipient: Address,
    approver: Address,
}

impl EscrowHarness {
    fn new(funding: i128) -> Self {
        let env = Env::default();
        env.mock_all_auths();
        let contract_id = env.register_contract(None, MicroPayContract);
        MicroPayContractClient::new(&env, &contract_id).initialize(&Address::generate(&env));
        let token = env
            .register_stellar_asset_contract_v2(Address::generate(&env))
            .address();
        let payer = Address::generate(&env);
        let recipient = Address::generate(&env);
        let approver = Address::generate(&env);
        token::StellarAssetClient::new(&env, &token).mint(&payer, &funding);
        Self {
            env,
            contract_id,
            token,
            payer,
            recipient,
            approver,
        }
    }

    fn client(&self) -> MicroPayContractClient<'_> {
        MicroPayContractClient::new(&self.env, &self.contract_id)
    }

    fn balance(&self, holder: &Address) -> i128 {
        token::Client::new(&self.env, &self.token).balance(holder)
    }
}

#[derive(Debug)]
struct MilestoneModel {
    escrows: Vec<TrackedEscrow>,
    payer_balance: i128,
    total_minted: i128,
    sequence: u32,
}

impl MilestoneModel {
    /// Exactly the rules `escrow.rs` enforces, applied to the model.
    fn create_would_succeed(&self, amount: i128, timeout: u32) -> bool {
        amount > 0 && timeout > 0 && timeout <= MAX_DISPUTE_TIMEOUT && self.payer_balance >= amount
    }

    fn approve_would_succeed(&self, id: u32) -> bool {
        matches!(self.escrows.get(id as usize), Some(e) if e.state == MilestoneState::Pending)
    }

    fn dispute_would_succeed(&self, id: u32) -> bool {
        self.approve_would_succeed(id)
    }

    fn cancel_would_succeed(&self, id: u32) -> bool {
        match self.escrows.get(id as usize) {
            Some(e) => e.state == MilestoneState::Disputed && self.sequence >= e.reclaim_after,
            None => false,
        }
    }

    /// released + refunded + held must equal deposited — expressed both on
    /// the records and on the actual token balances.
    fn assert_conservation(&self, t: &EscrowHarness) {
        let deposited: i128 = self.escrows.iter().map(|e| e.amount).sum();
        let released: i128 = self
            .escrows
            .iter()
            .filter(|e| e.state == MilestoneState::Approved)
            .map(|e| e.amount)
            .sum();
        let refunded: i128 = self
            .escrows
            .iter()
            .filter(|e| e.state == MilestoneState::Cancelled)
            .map(|e| e.amount)
            .sum();
        let held: i128 = self
            .escrows
            .iter()
            .filter(|e| e.state == MilestoneState::Pending || e.state == MilestoneState::Disputed)
            .map(|e| e.amount)
            .sum();
        assert_eq!(
            released + refunded + held,
            deposited,
            "record conservation broken: released={released}, refunded={refunded}, held={held}, \
             deposited={deposited}"
        );

        // Token-level: money only ever moves payer -> contract -> recipient|payer.
        let contract_balance = t.balance(&t.contract_id);
        let recipient_balance = t.balance(&t.recipient);
        let payer_balance = t.balance(&t.payer);
        assert_eq!(
            payer_balance + recipient_balance + contract_balance,
            self.total_minted,
            "balance conservation broken: payer={payer_balance}, recipient={recipient_balance}, \
             contract={contract_balance}, minted={}",
            self.total_minted
        );
        assert_eq!(payer_balance, self.payer_balance);
        assert_eq!(contract_balance, held);
        assert_eq!(recipient_balance, released);
    }
}

fn status_of(state: MilestoneState) -> EscrowStatus {
    match state {
        MilestoneState::Pending => EscrowStatus::Pending,
        MilestoneState::Approved => EscrowStatus::Approved,
        MilestoneState::Disputed => EscrowStatus::Disputed,
        MilestoneState::Cancelled => EscrowStatus::Cancelled,
    }
}

fn milestone_op_strategy() -> impl Strategy<Value = MilestoneOp> {
    prop_oneof![
        (100i128..1_000i128, 1u32..400u32)
            .prop_map(|(amount, timeout)| MilestoneOp::Create { amount, timeout }),
        (0u32..6u32).prop_map(MilestoneOp::TryApprove),
        (0u32..6u32).prop_map(MilestoneOp::TryDispute),
        (0u32..6u32).prop_map(MilestoneOp::TryCancel),
        (0u32..120u32).prop_map(MilestoneOp::Advance),
    ]
}

proptest! {
    #![proptest_config(ProptestConfig::with_cases(100))]

    /// Across any legal sequence of create/approve/dispute/cancel/advance —
    /// including attempts on unknown ids and on already-resolved escrows —
    /// released + refunded + held always equals deposited, on the records
    /// *and* on the token balances, and a disputed or cancelled escrow can
    /// never be approved (no double-spend after dispute).
    #[test]
    fn prop_milestone_escrow_conservation(
        ops in prop::collection::vec(milestone_op_strategy(), 10..50),
    ) {
        let funding: i128 = 20_000;
        let t = EscrowHarness::new(funding);
        let client = t.client();
        let mut model = MilestoneModel {
            escrows: Vec::new(),
            payer_balance: funding,
            total_minted: funding,
            sequence: t.env.ledger().sequence(),
        };

        for op in ops {
            match op {
                MilestoneOp::Create { amount, timeout } => {
                    let expected = model.create_would_succeed(amount, timeout);
                    let result = client.try_create_milestone_escrow(
                        &t.token,
                        &t.payer,
                        &t.recipient,
                        &amount,
                        &t.approver,
                        &timeout,
                    );
                    assert_eq!(result.is_ok(), expected,
                        "create(amount={amount}, timeout={timeout}) ok={} but model predicted {}",
                        result.is_ok(), expected);
                    if expected {
                        assert_eq!(result.unwrap().unwrap() as usize, model.escrows.len());
                        model.escrows.push(TrackedEscrow {
                            amount,
                            dispute_timeout: timeout,
                            reclaim_after: u32::MAX,
                            state: MilestoneState::Pending,
                        });
                        model.payer_balance -= amount;
                    }
                }
                MilestoneOp::TryApprove(id) => {
                    let expected = model.approve_would_succeed(id);
                    let result = client.try_approve_milestone(&id, &t.approver);
                    assert_eq!(result.is_ok(), expected,
                        "approve({id}) ok={} but model predicted {}", result.is_ok(), expected);
                    if let Some(entry) = model.escrows.get_mut(id as usize) {
                        if expected {
                            entry.state = MilestoneState::Approved;
                        }
                    }
                }
                MilestoneOp::TryDispute(id) => {
                    let expected = model.dispute_would_succeed(id);
                    let result = client.try_dispute_milestone(&id, &t.payer);
                    assert_eq!(result.is_ok(), expected,
                        "dispute({id}) ok={} but model predicted {}", result.is_ok(), expected);
                    if let Some(entry) = model.escrows.get_mut(id as usize) {
                        if expected {
                            // Dispute opens the reclaim window at the current
                            // ledger — the timing path the unit tests pin.
                            entry.reclaim_after =
                                model.sequence.saturating_add(entry.dispute_timeout);
                            entry.state = MilestoneState::Disputed;
                        }
                    }
                }
                MilestoneOp::TryCancel(id) => {
                    let expected = model.cancel_would_succeed(id);
                    let result = client.try_cancel_milestone_escrow(&id, &t.payer);
                    assert_eq!(result.is_ok(), expected,
                        "cancel({id}) ok={} but model predicted {}", result.is_ok(), expected);
                    if let Some(entry) = model.escrows.get_mut(id as usize) {
                        if expected {
                            entry.state = MilestoneState::Cancelled;
                            model.payer_balance += entry.amount;
                        }
                    }
                }
                MilestoneOp::Advance(k) => {
                    advance_by(&t.env, k);
                    model.sequence += k;
                }
            }

            model.assert_conservation(&t);
            for (id, entry) in model.escrows.iter().enumerate() {
                let record: MilestoneEscrowRecord = client.get_milestone_escrow(&(id as u32));
                assert_eq!(record.amount, entry.amount);
                assert_eq!(record.status, status_of(entry.state));
            }
        }
    }
}

/// Deterministic timing-boundary check on top of the randomized properties:
/// a disputed escrow becomes reclaimable exactly `dispute_timeout` ledgers
/// after the dispute — one ledger early must fail, at the boundary it must
/// succeed, and reclaiming twice must fail (saturating the refund bucket).
#[test]
fn test_milestone_reclaim_timing_boundary_and_no_double_refund() {
    let t = EscrowHarness::new(10_000);
    let client = t.client();
    let timeout: u32 = 700;
    let amount: i128 = 3_000;

    let id = client.create_milestone_escrow(
        &t.token,
        &t.payer,
        &t.recipient,
        &amount,
        &t.approver,
        &timeout,
    );
    let disputed_at = t.env.ledger().sequence();
    client.dispute_milestone(&id, &t.payer);

    advance_by(&t.env, timeout - 1);
    assert!(
        client.try_cancel_milestone_escrow(&id, &t.payer).is_err(),
        "reclaim one ledger early must fail"
    );

    advance_by(&t.env, 1);
    assert!(
        client.try_cancel_milestone_escrow(&id, &t.payer).is_ok(),
        "reclaim at the boundary must succeed"
    );
    assert_eq!(t.balance(&t.payer), 10_000);
    assert_eq!(t.balance(&t.contract_id), 0);

    // Second reclaim must fail: the refund cannot be collected twice.
    assert!(client.try_cancel_milestone_escrow(&id, &t.payer).is_err());
    assert!(client.try_approve_milestone(&id, &t.approver).is_err());
    assert_eq!(t.balance(&t.payer), 10_000);
    assert_eq!(t.balance(&t.contract_id), 0);
    let _ = disputed_at;
}
